UPDATE like_counts
SET
count = CASE

WHEN (count + #{delta}) >= 0 THEN (count + #{delta})
ELSE 0
END,
updated_at = #{now}
WHERE
entity_type = #{type}
AND entity_id = #{id}

AND count = #{oldCount}

UPDATE like_counts
SET
count = #{likeCount.count},
updated_at = #{likeCount.updatedAt}
WHERE
entity_type = #{likeCount.entityType}
AND entity_id = #{likeCount.entityId}

UPDATE like_counts SET count = CASE
WHEN entity_type = #{item.entityType} AND entity_id = #{item.entityId} THEN #{item.count}
ELSE count END, updated_at = CASE
WHEN entity_type = #{item.entityType} AND entity_id = #{item.entityId} THEN #{item.updatedAt}
ELSE updated_at END WHERE (entity_type, entity_id) IN
(#{item.entityType}, #{item.entityId})
